import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { QrReader } from 'react-qr-reader';
import './AttendanceScanner.css';

// Mock employee data (in a real app, this would come from an API or shared context)
const VALID_EMPLOYEES = [
  { id: 'E001', name: 'John Smith', department: 'IT' },
  { id: 'E002', name: 'Sarah Johnson', department: 'HR' },
  { id: 'E003', name: 'Mike Davis', department: 'PM' },
  { id: 'E004', name: 'Emily Brown', department: 'Design' },
  { id: 'E005', name: 'Robert Wilson', department: 'Business' },
  { id: 'E006', name: 'Lisa Anderson', department: 'IT' },
  { id: 'E007', name: 'James Martinez', department: 'Finance' },
  { id: 'E008', name: 'Jennifer Taylor', department: 'Marketing' },
];

// Suppress specific console warnings from zxing library
const originalWarn = console.warn;
const originalInfo = console.info;
console.warn = function(...args) {
  if (args[0]?.includes?.('BrowserCodeReader') || args[0]?.includes?.('Canvas2D')) {
    return;
  }
  originalWarn(...args);
};

console.info = function(...args) {
  if (args[0]?.includes?.('BrowserCodeReader') || 
      args[0]?.includes?.('HTMLCanvasElementLuminanceSource') ||
      args[0]?.includes?.('Multiple readback') ||
      args[0]?.includes?.('willReadFrequently')) {
    return;
  }
  originalInfo(...args);
};

const AttendanceScanner = ({ user, onLogout }) => {
  const [scanStatus, setScanStatus] = useState('idle'); // idle, success, error
  const [message, setMessage] = useState('');
  const [cameraError, setCameraError] = useState('');
  const [cameraReady, setCameraReady] = useState(false);
  const [qrReaderKey, setQrReaderKey] = useState(0);
  const isMountedRef = useRef(true);
  const navigate = useNavigate();

  // Request camera permissions on component mount
  useEffect(() => {
    isMountedRef.current = true;

    const requestCameraPermission = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment' },
          audio: false 
        });
        // Close the stream immediately, we just wanted to check permissions
        stream.getTracks().forEach(track => track.stop());
        if (isMountedRef.current) {
          setCameraReady(true);
          setCameraError('');
        }
      } catch (error) {
        if (isMountedRef.current) {
          setCameraReady(false);
          if (error.name === 'NotAllowedError') {
            setCameraError('Camera access denied. Please grant camera permissions in your browser settings.');
          } else if (error.name === 'NotFoundError') {
            setCameraError('No camera device found. Please connect a camera or check if it is already in use.');
          } else if (error.name === 'NotReadableError') {
            setCameraError('Camera is already in use by another application. Please close other apps using the camera.');
          } else {
            setCameraError(`Camera error: ${error.message || 'Unable to access camera'}`);
          }
          console.error('Camera permission error:', error);
        }
      }
    };

    requestCameraPermission();

    return () => {
      isMountedRef.current = false;
    };
  }, []);

  // Reset QR reader key when camera ready state changes
  useEffect(() => {
    if (cameraReady) {
      setQrReaderKey(prev => prev + 1);
    }
  }, [cameraReady]);

  // Simulate QR Scanner for demo (if camera is not available)
  const handleSimulateScan = (employeeId) => {
    validateScan(employeeId);
  };

  const validateScan = (scannedId) => {
    // 1. Validate Employee Exists
    const employee = VALID_EMPLOYEES.find(emp => emp.id === scannedId);
    
    if (!employee) {
      setScanStatus('error');
      setMessage(`Invalid QR Code: ${scannedId}. Employee not found.`);
      return;
    }

    // 2. Check Last Scan Status (from LocalStorage)
    const today = new Date().toISOString().split('T')[0];
    const storageKey = `attendance_${employee.id}_${today}`;
    const record = JSON.parse(localStorage.getItem(storageKey) || '{}');
    
    // Determine action based on history
    // If no record or has timeOut, next is Time In
    // If has timeIn but no timeOut, next is Time Out
    
    let action = '';
    const now = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

    if (!record.timeIn) {
      // New record for today -> Time In
      action = 'IN';
      record.timeIn = now;
      record.status = 'Present'; // Default
    } else if (record.timeIn && !record.timeOut) {
      // Has In, needs Out -> Time Out
      action = 'OUT';
      record.timeOut = now;
    } else {
      // Already has In and Out
      setScanStatus('error');
      setMessage(`Employee ${employee.name} has already completed attendance for today.`);
      return;
    }

    // Save back to storage
    localStorage.setItem(storageKey, JSON.stringify(record));

    // Update State
    setScanStatus('success');
    setMessage(`Successfully Checked ${action}: ${employee.name} (${employee.id}) at ${now}`);

    // Clear success message after 3 seconds
    setTimeout(() => {
      setScanStatus('idle');
      setMessage('');
    }, 3000);
  };

  return (
    <div className="scanner-page">
      {/* Simplified Header/Navbar */}
      <div className="scanner-navbar">
        <div className="scanner-logo">
          <span>⚡ Gracewell NEXUS</span>
        </div>
        <div className="scanner-user">
          <span>{user?.employeeName || 'User'}</span>
          <div className="user-avatar">
            {user?.employeeName ? user.employeeName.charAt(0) : 'U'}
          </div>
          <button onClick={onLogout} style={{background: 'none', border: 'none', color: 'white', cursor: 'pointer'}}>Logout</button>
        </div>
      </div>

      <div className="scanner-left-panel">
        <h1>Gracewell NEXUS</h1>
        <h2>Attendance Checker</h2>
      </div>

      <div className="scanner-right-panel">
        <button className="manual-entry-btn" onClick={() => navigate('/employee')}>
          <span>📝</span> Manual Entry
        </button>

        <div className="scanner-container">
          <div className="qr-frame">
            <div className="qr-frame-corners-2"></div>
            <div className="scanner-camera-wrapper">
              {cameraReady ? (
                <QrReader
                  key={qrReaderKey}
                  onResult={(result, error) => {
                    if (!!result && scanStatus === 'idle') {
                      validateScan(result?.text);
                    }
                  }}
                  constraints={{ 
                    video: { 
                      facingMode: 'environment',
                      width: { ideal: 1280 },
                      height: { ideal: 720 }
                    },
                    audio: false
                  }}
                  style={{ width: '100%', height: '100%' }}
                />
              ) : (
                <div style={{ 
                  display: 'flex', 
                  alignItems: 'center', 
                  justifyContent: 'center', 
                  height: '100%',
                  background: '#f5f5f5',
                  borderRadius: '8px'
                }}>
                  <div style={{ textAlign: 'center', color: '#666' }}>
                    <p style={{ fontSize: '16px', marginBottom: '10px' }}>📷 Camera Not Available</p>
                    <p style={{ fontSize: '12px', color: '#999' }}>Use demo buttons below to test</p>
                  </div>
                </div>
              )}
            </div>
          </div>

          <div className="scan-instruction">
            {cameraError ? (
              <div style={{ color: '#d32f2f', backgroundColor: '#ffebee', padding: '12px', borderRadius: '4px', marginBottom: '15px' }}>
                <strong>⚠️ Camera Error:</strong><br/>
                {cameraError}
              </div>
            ) : (
              <p>Please place your QR code front of the camera to begin the scan</p>
            )}
          </div>

          {/* Simulation Controls (Visible for Demo) */}
          <div style={{ marginTop: '30px', padding: '20px', border: '1px dashed #ccc', borderRadius: '10px' }}>
            <p style={{ marginBottom: '10px', color: '#666' }}>[Demo] Simulate Scan:</p>
            <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap', justifyContent: 'center' }}>
              {VALID_EMPLOYEES.slice(0, 4).map(emp => (
                <button 
                  key={emp.id}
                  onClick={() => handleSimulateScan(emp.id)}
                  style={{ padding: '8px 15px', cursor: 'pointer', backgroundColor: '#f0f0f0', border: '1px solid #ddd', borderRadius: '4px' }}
                >
                  {emp.name} ({emp.id})
                </button>
              ))}
              <button 
                onClick={() => handleSimulateScan('INVALID')}
                style={{ padding: '8px 15px', cursor: 'pointer', backgroundColor: '#ffebee', border: '1px solid #ffcdd2', borderRadius: '4px', color: '#c62828' }}
              >
                Invalid QR
              </button>
            </div>
          </div>

          {message && (
            <div className={`scan-status ${scanStatus === 'success' ? 'status-success' : 'status-error'}`}>
              {message}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AttendanceScanner;
